packages.setup:
for _kernel in ${kernels[@]}; do
    mkdir ${_kernel}
    bsdtar-static -xf %(sourcedir)/nvidia.tar.xz --strip-components=1 -C ${_kernel}

    pushd ${_kernel}
    # This is where patches would go
    # %patch %(pkgdir)/ibt-support.patch
    # Request by OGC: https://github.com/NVIDIA/open-gpu-kernel-modules/pull/1512
    [[ "${_kernel}" =~ "7.3" ]] && %patch %(pkgdir)/1512.patch
    popd
done

packages.install:
# ensure the umask is explicitly shown during build for reference
umask
_t=%(installroot)%(datadir)/%(name)
%install_dir %(installroot)%(datadir)/%(name)/
for p in 7777 6777 5777 4777 3777 2777 1777 0777 0775 0755
do
    touch ${_t}/file.${p}
    touch ${_t}/dir.${p}
    chmod -c ${p} ${_t}/file.${p} ${_t}/dir.${p}
done

